/* From Uiverse.io by PriyanshuGupta28 - Tags: checkbox, cool checkbox, checkmark */
.__UIV_SCOPE__ .input[type="checkbox"] {
  display: none;
}


  /* Style for the custom checkbox */
.__UIV_SCOPE__ .custom-checkbox {
  display: inline-block;
  width: 20px;
  height: 20px;
  border: 2px solid #333;
  border-radius: 4px;
  position: relative;
  cursor: pointer;
}

  /* Style for the custom checkmark */
.__UIV_SCOPE__ .custom-checkbox::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 10px;
  height: 10px;
  background-color: #333;
  border-radius: 2px;
  opacity: 0;
}

  /* Show the checkmark when checkbox is checked */
.__UIV_SCOPE__ .input[type="checkbox"]:checked + .custom-checkbox::after {
  opacity: 1;
}
